CACHE = {}

def nbits(n):
    b = 0
    while (1 << b) < n:
        b += 1
    return b

def lget(layout, names):
    for nm in names:
        try:
            if nm in layout:
                return int(layout[nm])
        except Exception:
            pass
    return None

def build_comp(layout):
    T = int(layout['T']); xb = int(layout['x_base']); yb = int(layout['y_base']); zb = int(layout['z_base'])
    GS = int(layout['GSEP']); FS = int(layout['FSEP']); QS = int(layout['QSEP'])
    Vin = max(xb + T, yb + T, zb + T, GS + 1, FS + 1, QS + 1)
    d = 32 * nbits(T + 1)
    P = Vin; S1 = Vin + 3; S2 = S1 + T
    if S2 + T > d:
        d = S2 + T
    s = np.sqrt(d); c1 = 50.0; beta = 1000.0; l2 = 60.0
    W = {}
    for nm in ('Wa1', 'Wc1', 'Wp1', 'Wa2', 'Wc2', 'Wp2', 'U1', 'V1', 'U2', 'V2'):
        W[nm] = np.zeros((d, d))
    W['Wo1'] = np.eye(d); W['Wo2'] = np.eye(d)
    W['Wa1'][0, P] = 1.0; W['Wa1'][1, P + 1] = 1.0
    W['Wp1'][0, P] = s * c1; W['Wp1'][0, P + 2] = -s * c1; W['Wp1'][1, P + 2] = -s * c1 / 2.0
    for k in range(T):
        W['Wp1'][0, xb + k] += s * c1 * beta * (2.0 + 2.0 * k)
        W['Wp1'][1, xb + k] += -s * c1 * beta / 2.0
        W['Wc1'][S1 + k, yb + k] = 1.0
        W['Wa2'][S1 + k, S1 + k] = 1.0
        W['Wa2'][P + 2, zb + k] = 1.0
        W['Wp2'][S1 + k, S1 + k] = s * l2
        W['Wc2'][S2 + k, zb + k] = 1.0
    W['Wp2'][P + 2, P + 2] = s * l2
    O = np.zeros((Vin, d))
    for k in range(T):
        O[zb + k, S2 + k] = 1.0
    W['O'] = O; W['d'] = d; W['Vin'] = Vin; W['P'] = P
    return W

def build_bind(layout):
    nv = int(layout['n_vars']); vb = int(layout['value_base']); nval = int(layout['values']); QS = int(layout['QSEP'])
    Vin = max(nv, vb + nval, QS + 1)
    h = lget(layout, ('hops', 'size', 'n_hops'))
    if h is None:
        h = max(1, (nv - 2) // 2)
    d = 32 * nbits(h + 1)
    P = Vin; PR = Vin + 3; S2 = PR + Vin
    if S2 + nval > d:
        d = S2 + nval
    s = np.sqrt(d); c1 = 50.0; l2 = 60.0
    W = {}
    for nm in ('Wa1', 'Wc1', 'Wp1', 'Wa2', 'Wc2', 'Wp2', 'U1', 'V1', 'U2', 'V2'):
        W[nm] = np.zeros((d, d))
    W['Wo1'] = np.eye(d); W['Wo2'] = np.eye(d)
    W['Wa1'][0, P] = 1.0; W['Wa1'][1, P + 1] = 1.0
    W['Wp1'][0, P] = s * c1; W['Wp1'][0, P + 2] = -s * c1; W['Wp1'][1, P + 2] = -s * c1 / 2.0
    for k in range(Vin):
        W['Wc1'][PR + k, k] = 1.0
    for k in range(nv):
        W['Wa2'][PR + k, PR + k] = 1.0
        W['Wp2'][PR + k, k] = s * l2
    for j in range(nval):
        W['Wa2'][P + 2, vb + j] = 1.0
        W['Wc2'][S2 + j, vb + j] = 1.0
    W['Wp2'][P + 2, P + 2] = s * l2 * 0.5
    O = np.zeros((Vin, d))
    for j in range(nval):
        O[vb + j, S2 + j] = 1.0
    W['O'] = O; W['d'] = d; W['Vin'] = Vin; W['P'] = P
    return W

def init(layout):
    if 'T' in layout:
        key = ('comp', int(layout['T']), int(layout['x_base']), int(layout['y_base']), int(layout['z_base']), int(layout['GSEP']), int(layout['FSEP']), int(layout['QSEP']))
        if key not in CACHE:
            CACHE[key] = build_comp(layout)
    else:
        key = ('bind', int(layout['n_vars']), int(layout['value_base']), int(layout['values']), int(layout['QSEP']), lget(layout, ('hops', 'size', 'n_hops')))
        if key not in CACHE:
            CACHE[key] = build_bind(layout)
    d = CACHE[key]['d']
    return {'key': key, 't': 0, 'A1': np.zeros((0, d)), 'C1': np.zeros((0, d)), 'A2': np.zeros((0, d)), 'C2': np.zeros((0, d)), 'h': np.zeros(d)}

def round_step(state, W, h, l):
    d = W['d']
    a = W['Wa' + l] @ h
    c = W['Wc' + l] @ h
    p = W['Wp' + l] @ h
    A = np.vstack([state['A' + l], a[None, :]])
    C = np.vstack([state['C' + l], c[None, :]])
    state['A' + l] = A
    state['C' + l] = C
    sc = (A @ p) / np.sqrt(d)
    sc = sc - sc.max()
    w = np.exp(sc)
    w = w / w.sum()
    r = w @ C
    g = h + W['Wo' + l] @ r
    return g + W['U' + l] @ np.maximum(0.0, W['V' + l] @ g)

def update(state, token):
    W = CACHE[state['key']]
    d = W['d']; P = W['P']; t = state['t']
    h = np.zeros(d)
    tok = int(token)
    if 0 <= tok < W['Vin']:
        h[tok] = 1.0
    h[P] = float(t); h[P + 1] = float(t) * float(t); h[P + 2] = 1.0
    h = round_step(state, W, h, '1')
    h = round_step(state, W, h, '2')
    state['h'] = h
    state['t'] = t + 1
    return state

def predict(state):
    W = CACHE[state['key']]
    logits = W['O'] @ state['h']
    return int(np.argmax(logits))

